[def:exact]($a,$b){ return len($a)==len($b) and contains($a,$b,true) }
[def:validnumber]($x,$file,$row,$field){
 [try]{ return number($x) }[catch]{ assert false,"숫자 오류",{file:$file,row:$row,field:$field,value:$x,cause:$error.message} }
}
$cat=$src[0].data.items
$opening=$src[1].data.items
assert len($opening)==320,"기초 재고 쌍 수 오류",{file:"opening.json",actual:len($opening)}
$cg=$cat >> [table:groupby]{by:"sku",agg:{n:["count"]}}
$og=$opening >> [table:groupby]{by:["warehouse","sku"],agg:{n:["count"]}}
assert all(map($cg.items,($r)=>$r.n==1)),"상품 중복 키",{file:"catalog.json",groups:$cg.items}
assert all(map($og.items,($r)=>$r.n==1)),"기초 재고 중복 키",{file:"opening.json",groups:$og.items}
$cat=$cat >> [table:each]{
 assert len(strip($it.sku))>0,"빈 상품 키",{file:"catalog.json",row:$i+1}
 $p=[fn:validnumber]{x:$it.pack,file:"catalog.json",row:$i+1,field:"pack"}
 $t=[fn:validnumber]{x:$it.threshold,file:"catalog.json",row:$i+1,field:"threshold"}
 assert $p>0 and $p%1==0,"유효하지 않은 pack",{file:"catalog.json",row:$i+1,sku:$it.sku,pack:$p}
 return {sku:$it.sku,pack:$p,threshold:$t}
}
$opening=$opening >> [table:each]{
 assert len(strip($it.warehouse))>0 and len(strip($it.sku))>0,"빈 재고 키",{file:"opening.json",row:$i+1}
 $n=[fn:validnumber]{x:$it.opening,file:"opening.json",row:$i+1,field:"opening"}
 return {warehouse:$it.warehouse,sku:$it.sku,opening:$n}
}
$badcat=[table:join]{left:$opening,right:$cat,on:"sku",how:"anti"}
assert len($badcat.items)==0,"등록되지 않은 기초 재고 상품",{file:"opening.json",keys:$badcat.items}
$raw=$src[2:6] >> [table:each]{mode:"flat_map"}{
 $file=$it.file
 $it.data.items >> [table:each]{
  assert len(strip($it.id))>0,"빈 입출고 id",{file:$file,row:$i+2}
  $d=[fn:validnumber]{x:$it.delta,file:$file,row:$i+2,field:"delta"}
  return {id:$it.id,warehouse:$it.warehouse,sku:$it.sku,delta:$d,file:$file,row:$i+2,signature:json($it)}
 }
}
$ordered=$raw >> [table:sort]{by:"id"}
$unique=[]
$duplicates=[]
$previous={id:"",signature:""}
[repeat:len($ordered)]{
 $r=$ordered[$i]
 [if:[fn:exact]{a:$r.id,b:$previous.id}]{
  assert [fn:exact]{a:$r.signature,b:$previous.signature},"동일 id의 내용 충돌",{first:$previous,conflict:$r}
  $duplicates=$duplicates+[$r]
 }[else]{ $unique=$unique+[$r] }
 $previous=$r
}
$res=$src[6].data.items >> [table:each]{
 assert len(strip($it.id))>0,"빈 예약 id",{file:"reservations.csv",row:$i+2}
 assert [fn:exact]{a:$it.status,b:"active"} or [fn:exact]{a:$it.status,b:"cancelled"},"미지원 예약 status",{file:"reservations.csv",row:$i+2,status:$it.status}
 $q=[fn:validnumber]{x:$it.qty,file:"reservations.csv",row:$i+2,field:"qty"}
 assert $q>=0,"음수 예약 qty",{file:"reservations.csv",row:$i+2,qty:$q}
 return {id:$it.id,warehouse:$it.warehouse,sku:$it.sku,qty:$q,status:$it.status,file:"reservations.csv",row:$i+2}
}
$badmov=[table:join]{left:$raw,right:$opening,on:["warehouse","sku"],how:"anti"}
$badres=[table:join]{left:$res,right:$opening,on:["warehouse","sku"],how:"anti"}
assert len($badmov.items)==0,"입출고 연결 실패",{rows:$badmov.items}
assert len($badres.items)==0,"예약 연결 실패",{rows:$badres.items}
$active=$res >> [table:filter]{where:($r)=>$r.status=="active"}
$cancelled=$res >> [table:filter]{where:($r)=>$r.status=="cancelled"}
$net=$unique >> [table:groupby]{by:["warehouse","sku"],agg:{net:["sum","delta"]}}
$reserved=$active >> [table:groupby]{by:["warehouse","sku"],agg:{reserved:["sum","qty"]}}
$counts={catalog:len($cat),opening:len($opening),movements_raw:len($raw),movements_unique:len($unique),duplicate_movements:len($duplicates),reservations:len($res),active_reservations:len($active),cancelled_reservations:len($cancelled)}
$files=$src[2:6] >> [table:each]{
 $f=$it.file
 return {file:$f,raw:len($it.data.items),processed:len(filter($unique,($r)=>$r.file==$f)),duplicates:len(filter($duplicates,($r)=>$r.file==$f)),excluded:0}
}
assert $counts.movements_raw==$counts.movements_unique+$counts.duplicate_movements,"입출고 건수 대사 실패"
assert $counts.reservations==$counts.active_reservations+$counts.cancelled_reservations,"예약 건수 대사 실패"
return {catalog:$cat,opening:$opening,net:$net.items,reserved:$reserved.items,counts:$counts,files:$files,duplicates:$duplicates}

