$a=[table:join]{left:$p.opening,right:$p.catalog,on:"sku",how:"left"}
$b=[table:join]{left:$a.items,right:$p.net,on:["warehouse","sku"],how:"left",defaults:{net:0}}
$c=[table:join]{left:$b.items,right:$p.reserved,on:["warehouse","sku"],how:"left",defaults:{reserved:0}}
assert len($a.items)==320 and len($b.items)==320 and len($c.items)==320,"연결 후 행 누락 또는 증식"
$cols=["warehouse","sku","opening","net","reserved","pack","target","available","deficit","reorder"]
$items=$c.items >> [table:compute]{set:($r)=>{target:$r.threshold+20,available:$r.opening+$r.net-$r.reserved}} >> [table:compute]{set:($r)=>{deficit:max(0,$r.target-$r.available)}} >> [table:compute]{set:($r)=>{reorder:$r.deficit+($r.pack-$r.deficit%$r.pack)%$r.pack}} >> [table:select]{columns:$cols} >> [table:sort]{by:["warehouse","sku"]}
assert all(map($items,($r)=>$r.reorder%$r.pack==0 and $r.reorder>=$r.deficit and ($r.reorder==0 or $r.reorder-$r.pack<$r.deficit))),"최소 pack 배수 검증 실패"
$wg=$items >> [table:groupby]{by:"warehouse",agg:{available:["sum","available"],deficit:["sum","deficit"],reorder:["sum","reorder"]}}
$warehouses=$wg.items >> [table:sort]{by:"warehouse"} >> [table:select]{columns:["warehouse","available","deficit","reorder"]}
$top10=$items >> [table:compute]{set:($r)=>{negative_deficit:0-$r.deficit}} >> [table:sort]{by:["negative_deficit","warehouse","sku"]} >> [table:select]{columns:$cols} >> [table:take]{n:10}
return {inventory:{offset:20,items:$items,warehouses:$warehouses,top10:$top10,counts:$p.counts},files:$p.files,negative_available:len(filter($items,($r)=>$r.available<0)),totals:{available:reduce($items,0,($a,$r)=>$a+$r.available),deficit:reduce($items,0,($a,$r)=>$a+$r.deficit),reorder:reduce($items,0,($a,$r)=>$a+$r.reorder)}}

