return {inventory:{offset:20,items:$items,warehouses:$warehouses,top10:$top10,counts:$p.counts},files:$p.files,negative_available:len(filter($items,($r)=>$r.available<0)),totals:{available:reduce($items,0,($a,$r)=>$a+$r.available),deficit:reduce($items,0,($a,$r)=>$a+$r.deficit),reorder:reduce($items,0,($a,$r)=>$a+$r.reorder)}}

[def:mdtable]($rows,$columns){
 $lines=map($rows,($r)=>"| "+join(" | ",map($columns,($k)=>text($r[$k])))+" |")
 return "| "+join(" | ",$columns)+" |\n| "+join(" | ",map($columns,($k)=>"---"))+" |\n"+join("\n",$lines)+"\n"
}
$x=$calc.inventory
$iw=[self:write]{path:f"${$out}/inventory.json",content:json($x)}
$read=[self:read]{path:$iw.path}
$v=$read.data
assert json($v)==json($x),"저장 JSON 내용 불일치",{path:$iw.path}
assert keys($v)==["offset","items","warehouses","top10","counts"] and $v.offset==20,"JSON 최상위 구조 오류"
$columns=["warehouse","sku","opening","net","reserved","pack","target","available","deficit","reorder"]
$numbers=$columns[2:]
assert len($v.items)==320 and len($v.top10)==10,"저장 행수 오류"
$checks=$v.items >> [table:each]{
 $r=$it
 assert keys($r)==$columns,"행 키 오류",{warehouse:$r.warehouse,sku:$r.sku}
 assert all(map($numbers,($k)=>json($r[$k])==json(number($r[$k])))),"숫자 타입 오류",{warehouse:$r.warehouse,sku:$r.sku}
 assert $r.available==$r.opening+$r.net-$r.reserved and $r.deficit==max(0,$r.target-$r.available),"재고 공식 검증 실패",{row:$r}
 assert $r.pack>0 and $r.reorder%$r.pack==0 and $r.reorder>=$r.deficit and ($r.reorder==0 or $r.reorder-$r.pack<$r.deficit),"발주 최소 배수 검증 실패",{row:$r}
 $catalog=filter($prepared.catalog,($c)=>$c.sku==$r.sku)
 assert len($catalog)==1 and $r.pack==$catalog[0].pack and $r.target==$catalog[0].threshold+20,"상품 연결 검증 실패",{row:$r}
 return true
}
$sorted=$v.items >> [table:sort]{by:["warehouse","sku"]}
assert json($sorted)==json($v.items),"items 정렬 오류"
$whcheck=$v.warehouses >> [table:each]{
 $w=$it
 $rows=filter($v.items,($r)=>$r.warehouse==$w.warehouse)
 assert keys($w)==["warehouse","available","deficit","reorder"],"창고 행 키 오류"
 assert $w.available==reduce($rows,0,($a,$r)=>$a+$r.available) and $w.deficit==reduce($rows,0,($a,$r)=>$a+$r.deficit) and $w.reorder==reduce($rows,0,($a,$r)=>$a+$r.reorder),"창고 집계 대사 실패",{warehouse:$w.warehouse}
