[def:검사]($rows,$file,$kind,$cols) {
 $results=$rows >> [table:each]{on_error:"collect"} {
  $loc={file:$file,row:$i+($kind=="catalog" or $kind=="opening" ? 1 : 2)}
  assert sorted(keys($it))==sorted($cols),"필드 불일치",{**$loc,actual:keys($it),expected:$cols}
  assert len(strip($it.sku))>0,"빈 sku",$loc
  [if:$kind!="catalog"] { assert len(strip($it.warehouse))>0,"빈 warehouse",$loc }
  [if:$kind=="catalog"] {
   $n=number($it.pack); $t=number($it.threshold)
   assert $n>0 and $t>=0,"pack은 양수, threshold는 0 이상이어야 함",{**$loc,raw:$it}
   return {raw:$it,file:$file,row:$loc.row,value:{sku:$it.sku,pack:$n,threshold:$t}}
  }
  [if:$kind=="opening"] {
   $n=number($it.opening)
   assert $n>=0,"음수 기초 재고",{**$loc,raw:$it}
   return {raw:$it,file:$file,row:$loc.row,value:{warehouse:$it.warehouse,sku:$it.sku,opening:$n}}
  }
  assert len(strip($it.id))>0,"빈 id",$loc
  [if:$kind=="movement"] {
   $n=number($it.delta)
   return {raw:$it,file:$file,row:$loc.row,value:{**$it,delta:$n}}
  }
  $n=number($it.qty)
  assert $n>=0,"음수 예약량",{**$loc,raw:$it}
  assert $it.status in ["active","cancelled"],"알 수 없는 예약 status",{**$loc,raw:$it}
  return {raw:$it,file:$file,row:$loc.row,value:{**$it,qty:$n}}
 }
 $errors=$results >> [table:each]{mode:"flat_map"} {
  [if:is_ok($it)] {return []}
  return [{file:$file,row:$i+($kind=="catalog" or $kind=="opening" ? 1 : 2),error:error_of($it)}]
 }
 assert len($errors)==0,"원천 행 검증 실패",{errors:$errors}
 return map($results,($r)=>unwrap($r))
}
