[def:원천검사]($rows,$file,$cols,$numeric,$nonnegative,$keycols,$kind,$start) {
 $checks=$rows >> [table:each]{on_error:"collect"} {
  $loc={file:$file,row:$i+$start,raw:$it}
  assert sorted(keys($it))==sorted($cols),"필드 불일치",$loc
  assert all(map($keycols,($k)=>len(strip(get($it,$k)))>0)),"빈 키",$loc
  $numbers=map($numeric,($k)=>number(get($it,$k)))
  assert all(map($nonnegative,($k)=>number(get($it,$k))>=0)),"음수 수량/기준",$loc
  [if:$kind=="catalog"] {assert number(get($it,"pack"))>0,"pack은 양수여야 함",$loc}
  [if:$kind=="reservation"] {assert get($it,"status") in ["active","cancelled"],"알 수 없는 status",$loc}
  return {raw:$it,file:$file,row:$i+$start}
 }
 $errors=$checks >> [table:each]{mode:"flat_map"} {
  [if:is_ok($it)] {return []}
  return [{file:$file,row:$i+$start,error:error_of($it)}]
 }
 assert len($errors)==0,"원천 검증 실패",{errors:$errors}
 return map($checks,($r)=>unwrap($r))
}
